export const title = "Where to Put a Docking Station on a Small Desk";
export const metaTitle = "Where to Put a Docking Station on a Small Desk";
export const metaDescription = "Choose a dock location around connected plugs, ventilation instructions, daily access, and the power supply footprint. A research-based guide from DeskFinds.";
export const author = "Jamie Cole, Lead Product Researcher";
export const datePublished = "2026-10-28";
export const readTime = "11 min";
